insert into public.education_lists(id,kind,items) values
('d01','do',array['Latihan napas (diafragma dan pursed-lip) setiap hari.','Minum cukup air agar dahak encer; batuk efektif.','Berhenti merokok dan hindari asap serta debu.','Aktivitas bertahap dengan jeda istirahat.']),
('a01','avoid',array['Merokok atau berada di lingkungan berasap.','Menahan batuk berdahak.','Memaksa aktivitas hingga sesak berat.']),
('r01','red',array['Sesak napas mendadak memburuk atau napas sangat cepat.','Nyeri dada, batuk darah, atau bibir kebiruan.','Demam tinggi atau kesadaran menurun.']),
('a02','avoid',array['Merokok atau berada di lingkungan berasap.','Menahan batuk berdahak.','Memaksa aktivitas hingga sesak berat.','Memaksa olahraga berat saat lelah berlebihan.']),
('d02','do',array['Aktivitas bertahap dengan pacing; tambah sedikit demi sedikit.','Latihan napas dan relaksasi harian.','Jaga pola tidur teratur.','Cari dukungan keluarga dan tenaga kesehatan.']),
('a03','avoid',array['Pola semua-atau-tidak sama sekali (aktif berlebihan lalu istirahat total).','Menunggu nyeri hilang total sebelum bergerak.','Mengonsumsi obat nyeri berlebihan tanpa petunjuk.']),
('r02','red',array['Nyeri baru yang berbeda dari biasanya.','Kelemahan, mati rasa, atau gangguan BAK/BAB.','Demam, penurunan berat badan, atau perasaan putus asa/berniat menyakiti diri.']),
('d03','do',array['Lakukan latihan keseimbangan dan penguatan tiap hari.','Amankan rumah: lantai tidak licin, pencahayaan cukup, pegangan di kamar mandi.','Gunakan alas kaki yang pas dan alat bantu jalan sesuai anjuran.','Periksa penglihatan dan tinjau obat bersama dokter.']),
('a04','avoid',array['Berjalan di tempat licin atau gelap.','Berdiri tiba-tiba dari duduk atau berbaring.','Berhenti beraktivitas karena takut jatuh.']),
('r03','red',array['Jatuh dengan cedera atau tidak bisa bangun sendiri.','Pusing, pingsan, atau nyeri dada.','Kelemahan atau bicara pelo yang tiba-tiba.','Penurunan berat badan atau kondisi umum memburuk.']),
('d04','do',array['Lakukan latihan sesuai program secara teratur.','Naikkan aktivitas bertahap sesuai kemampuan.','Catat perkembangan dan sampaikan saat kontrol.']),
('a05','avoid',array['Memaksakan aktivitas yang memperberat nyeri.','Berhenti beraktivitas total.','Mengobati sendiri dengan cara yang belum jelas manfaatnya.']),
('r04','red',array['Nyeri makin berat atau tidak membaik setelah beberapa minggu.','Muncul kelemahan, kesemutan, bengkak, atau demam baru.','Keluhan baru yang membuat Anda khawatir.']),
('d05','do',array['Perhatikan hubungan nyeri dengan gerak, makan, dan BAB.','Lakukan latihan napas dan relaksasi.','Periksa ke dokter untuk memastikan tidak ada masalah organ dalam.']),
('a06','avoid',array['Menahan nyeri hebat tanpa memeriksakan diri.','Mengonsumsi obat tanpa petunjuk.']),
('r05','red',array['Demam, muntah terus, BAB berdarah/hitam.','Nyeri hebat mendadak atau perut keras.','Penurunan berat badan tanpa sebab atau kemungkinan hamil.']),
('d06','do',array['Ikuti instruksi dokter (penyangga, weight bearing, batas gerak).','Lakukan latihan sesuai program dan naikkan bertahap.','Jaga luka tetap bersih dan kering bila ada.','Gunakan alat bantu jalan sesuai anjuran.']),
('a07','avoid',array['Menumpu beban atau menggerakkan sendi melebihi batas yang dianjurkan.','Mengangkat beban berat sebelum diizinkan.','Merokok (menghambat penyembuhan tulang dan luka).']),
('r06','red',array['Demam, luka merah/bernanah/terbuka.','Betis bengkak, nyeri, atau hangat; sesak napas mendadak.','Nyeri makin hebat atau kesemutan/baal baru.','Ujung anggota gerak dingin atau kebiruan.']),
('d07','do',array['Ikuti instruksi dokter (penyangga, weight bearing, batas gerak).','Lakukan latihan sesuai program dan naikkan bertahap.','Jaga luka tetap bersih dan kering bila ada.','Gunakan alat bantu jalan sesuai anjuran.','Rawat kulit stump setiap hari dan periksa kemerahan/luka.','Posisikan stump lurus (hindari bantal di bawah lutut).']),
('d08','do',array['Lindungi area cedera 1-3 hari pertama; kompres dingin 10-15 menit bila bengkak.','Mulai gerak ringan bertahap sesuai arahan terapis.','Lanjutkan latihan penguatan sebelum kembali olahraga.']),
('a08','avoid',array['Memaksa aktivitas atau olahraga sebelum nyeri dan kekuatan membaik.','Pijat keras atau panas berlebih pada cedera baru.','Mengabaikan nyeri tajam saat bergerak.']),
('r07','red',array['Deformitas atau tidak bisa menumpu/menggerakkan sama sekali.','Baal, ujung dingin/pucat, atau kebiruan.','Bengkak yang cepat membesar atau nyeri makin hebat.','Demam atau area merah dan hangat.']),
('d09','do',array['Gunakan alas kaki yang menopang dan sesuai ukuran.','Lakukan peregangan dan penguatan sesuai program.','Naikkan aktivitas secara bertahap.']),
('a09','avoid',array['Berjalan tanpa alas kaki di permukaan keras saat nyeri.','Meningkatkan jarak lari atau aktivitas terlalu cepat.','Sepatu sempit atau hak tinggi.']),
('r08','red',array['Tidak bisa menumpu sama sekali atau terlihat berubah bentuk.','Kaki bengkak, merah, hangat disertai demam.','Kaki dingin, pucat, atau kebiruan.','Luka kaki sulit sembuh (terutama bila diabetes).']),
('d10','do',array['Tetap bergerak ringan setiap hari; latihan rentang gerak sendi.','Minum obat sesuai petunjuk dokter dan kontrol rutin.','Hangatkan sendi sebelum latihan bila kaku.','Istirahat cukup saat kambuh, lalu naikkan aktivitas pelan.']),
('a10','avoid',array['Memaksa latihan berat saat sendi sedang bengkak dan merah.','Menghentikan obat tanpa petunjuk dokter.','Menumpu beban berulang pada sendi yang meradang.']),
('r09','red',array['Sendi baru bengkak, merah, hangat, atau demam.','Kelemahan, mati rasa, atau gangguan penglihatan/mata merah.','Penurunan berat badan atau sesak napas.']),
('d11','do',array['Atur ergonomi kerja/belajar: layar sejajar mata, kursi menopang punggung.','Berdiri atau bergerak tiap 30-45 menit.','Lakukan latihan postur dan penguatan secara teratur.']),
('a11','avoid',array['Duduk membungkuk atau menunduk lama.','Membawa beban asimetris (tas satu bahu) terlalu berat.','Memaksakan postur kaku sepanjang hari.']),
('r10','red',array['Nyeri makin berat atau menjalar disertai kesemutan.','Kelainan bentuk yang cepat memburuk (terutama pada anak/remaja).','Gangguan napas atau nyeri dada.']),
('a12','avoid',array['Memaksa aktivitas atau olahraga sebelum nyeri dan kekuatan membaik.','Pijat keras atau panas berlebih pada cedera baru.','Mengabaikan nyeri tajam saat bergerak.','Gerakan lengan ke atas-belakang secara ekstrem saat fase awal.']),
('d12','do',array['Tetap bergerak dalam batas nyaman agar sendi tidak kaku.','Lakukan latihan penguatan paha dan pinggul sesuai program.','Jaga berat badan ideal.']),
('a13','avoid',array['Jongkok dalam atau berlutut lama saat nyeri.','Naik-turun tangga berulang saat nyeri.','Olahraga lompat atau lari sebelum dinyatakan aman.']),
('r11','red',array['Lutut terkunci dan tidak bisa diluruskan.','Lutut bengkak cepat, merah, hangat, atau demam.','Tidak bisa menumpu setelah cedera.','Betis bengkak dan nyeri (curiga bekuan darah).']),
('d13','do',array['Gerakkan bahu ringan setiap hari dalam batas nyaman.','Jaga postur; hindari tidur menindih bahu yang sakit.','Lakukan latihan sesuai program secara teratur.']),
('a14','avoid',array['Mengangkat beban berat di atas kepala saat nyeri.','Gerakan menarik atau menyentak mendadak.','Mendiamkan bahu sama sekali.']),
('r12','red',array['Bahu tidak bisa digerakkan atau berubah bentuk setelah cedera.','Nyeri dada atau lengan kiri disertai sesak/keringat dingin.','Lengan lemah, kesemutan, atau bengkak mendadak.','Demam atau bahu merah dan hangat.']),
('d14','do',array['Atur layar/ponsel sejajar mata dan istirahat tiap 30 menit.','Gunakan bantal yang menjaga leher tetap lurus saat tidur.','Lakukan latihan leher dan bahu sesuai program.']),
('a15','avoid',array['Menunduk lama saat memakai ponsel atau laptop.','Memutar atau menarik leher dengan paksa.','Tidur tengkurap.']),
('r13','red',array['Pusing berputar hebat, pandangan ganda, bicara pelo, atau sulit menelan.','Lengan atau tangan makin lemah atau kesemutan menetap.','Sulit berjalan atau tangan makin kikuk.','Nyeri leher setelah kecelakaan atau jatuh.']),
('d15','do',array['Atur postur dan ergonomi kerja; istirahat dari layar tiap 30 menit.','Tidur cukup dan teratur; minum cukup air.','Catat pemicu dan frekuensi nyeri kepala.','Lakukan latihan leher-bahu dan relaksasi.']),
('a16','avoid',array['Menunduk lama atau menahan ketegangan leher dan bahu.','Pemakaian obat nyeri berlebihan tanpa petunjuk.','Melewatkan makan dan kurang tidur.']),
('r14','red',array['Nyeri kepala terburuk seumur hidup atau muncul mendadak.','Demam dengan leher kaku.','Kelemahan, bicara pelo, atau gangguan penglihatan.','Nyeri kepala setelah benturan kepala.']),
('a17','avoid',array['Pola semua-atau-tidak sama sekali (aktif berlebihan lalu istirahat total).','Menunggu nyeri hilang total sebelum bergerak.','Mengonsumsi obat nyeri berlebihan tanpa petunjuk.','Memaksa olahraga berat saat tubuh sangat lelah.']),
('d16','do',array['Lakukan latihan lewat permainan setiap hari.','Libatkan orang tua dan pengasuh dalam latihan.','Beri stimulasi sesuai usia dan perkembangan.','Catat perkembangan anak untuk dibahas saat kontrol.']),
('a18','avoid',array['Memaksa anak melakukan gerakan hingga menangis atau kesakitan.','Membandingkan terlalu keras dengan anak lain.','Membiarkan anak dalam satu posisi terlalu lama.']),
('r15','red',array['Kejang, kelemahan mendadak, atau tidak mau menggerakkan anggota gerak.','Demam dengan nyeri sendi atau pincang.','Kemampuan yang sudah dimiliki hilang (kemunduran).']),
('a19','avoid',array['Memaksa aktivitas atau olahraga sebelum nyeri dan kekuatan membaik.','Pijat keras atau panas berlebih pada cedera baru.','Mengabaikan nyeri tajam saat bergerak.','Pijat keras atau panas berlebih pada memar baru.']),
('r16','red',array['Nyeri makin hebat dengan otot tegang atau keras disertai baal (segera ke IGD).','Bengkak makin besar.','Tidak bisa menggerakkan sendi sama sekali.']),
('d17','do',array['Lakukan latihan napas dalam dan peregangan dada-punggung atas.','Atur posisi duduk dan istirahat tiap 30-45 menit.','Tetap bergerak dalam batas nyaman.']),
('a20','avoid',array['Duduk membungkuk lama.','Menahan napas saat menahan nyeri.','Mengangkat beban berat dengan punggung membulat.']),
('r17','red',array['Nyeri dada, sesak napas, atau keringat dingin.','Demam atau penurunan berat badan tanpa sebab.','Nyeri hebat di malam hari.','Kelemahan atau baal pada tungkai.']),
('d18','do',array['Tetap aktif dengan jalan ringan dalam batas nyaman.','Lakukan latihan penguatan pinggul sesuai program.','Atur posisi duduk dan tidur (bantal di antara lutut saat miring).']),
('a21','avoid',array['Duduk bersila atau menyilang kaki bila memicu nyeri.','Tidur menindih sisi yang nyeri.','Latihan berat sebelum nyeri membaik.']),
('r18','red',array['Demam disertai nyeri panggul dan sulit menumpu.']),
('d19','do',array['Istirahatkan tangan dari gerakan pemicu secara bergantian.','Lakukan latihan dan peregangan sesuai program.','Perbaiki ergonomi saat mengetik, memegang ponsel, atau bekerja.']),
('a22','avoid',array['Menggenggam atau menjepit kuat berulang.','Posisi pergelangan tertekuk ekstrem dalam waktu lama.']),
('r19','red',array['Jari atau tangan pucat, biru, dingin, atau kesemutan menetap.','Kelemahan tangan yang makin berat.','Bengkak merah hangat disertai demam.','Deformitas atau tidak bisa menggerakkan jari setelah cedera.']),
('d20','do',array['Hindari posisi atau gerakan yang memicu gejala; ubah posisi berkala.','Lakukan latihan gerak saraf dan peregangan sesuai program.','Kontrol penyakit penyerta (mis. gula darah).']),
('a23','avoid',array['Menekan atau menumpu pada area saraf (mis. siku/pergelangan) terlalu lama.','Posisi sendi ekstrem dalam waktu lama.','Mengabaikan kelemahan atau baal yang makin berat.']),
('r20','red',array['Kelemahan yang cepat memburuk atau kedua sisi terkena.','Gangguan BAK/BAB.','Luka yang tidak terasa atau sulit sembuh pada area yang baal.','Nyeri hebat malam hari atau penurunan berat badan.']),
('d21','do',array['Tetap aktif dan lanjutkan aktivitas ringan; hindari tirah baring lama.','Ganti posisi tiap 30-45 menit.','Angkat beban dengan menekuk lutut dan beban dekat badan.','Rutin lakukan latihan di rumah sesuai program.']),
('a24','avoid',array['Membungkuk atau memutar badan sambil mengangkat beban.','Duduk atau berdiri sangat lama tanpa jeda.','Berhenti beraktivitas karena takut nyeri.']),
('r21','red',array['Sulit menahan BAK/BAB atau baal di area selangkangan.','Kelemahan tungkai makin berat atau kesemutan meluas.','Demam, nyeri hebat di malam hari, atau berat badan turun tanpa sebab.','Nyeri setelah jatuh atau benturan keras.']),
('d22','do',array['Perkuat otot penyangga sendi dengan latihan terkontrol.','Gerakkan sendi dalam rentang aman, bukan rentang ekstrem.','Gunakan penyangga bila disarankan saat aktivitas berat.']),
('a25','avoid',array['Peregangan agresif atau mengunci sendi saat berdiri.','Memutar atau menarik sendi hingga ujung gerak.','Aktivitas yang memicu sendi sering lepas.']),
('r22','red',array['Sendi lepas dan tidak kembali, nyeri hebat, atau bengkak cepat.','Pusing berdiri, pingsan, atau berdebar.','Mudah memar parah atau luka sulit sembuh.']),
('d23','do',array['Ikuti instruksi dokter (penyangga, weight bearing, batas gerak).','Lakukan latihan sesuai program dan naikkan bertahap.','Jaga luka tetap bersih dan kering bila ada.','Gunakan alat bantu jalan sesuai anjuran.','Periksa kulit stump sebelum dan sesudah memakai prostesis.']),
('d24','do',array['Gerakkan bahu ringan setiap hari dalam batas nyaman.','Jaga postur; hindari tidur menindih bahu yang sakit.','Lakukan latihan sesuai program secara teratur.','Gerak bahu setiap hari dalam batas nyeri yang dapat ditoleransi.']),
('r23','red',array['Nyeri hebat dan tidak bisa menumpu setelah jatuh.','Demam disertai nyeri sendi panggul.','Kelemahan tungkai atau gangguan BAK/BAB.','Nyeri malam yang makin berat.']),
('d25','do',array['Istirahatkan dari gerakan pemicu, lalu mulai latihan bertahap.','Gunakan alat bantu/penyangga bila disarankan.','Perbaiki cara memegang atau mengangkat benda.']),
('a26','avoid',array['Gerakan menggenggam atau memutar yang berulang dan kuat.','Mengangkat beban dengan lengan lurus saat nyeri.']),
('r24','red',array['Siku bengkak, merah, hangat disertai demam.','Siku berubah bentuk atau tidak bisa digerakkan setelah cedera.','Kesemutan atau lemah di tangan yang makin berat.']),
('d26','do',array['Lakukan latihan wajah di depan cermin dengan gerakan halus.','Jaga mata tetap lembap dan terlindungi bila sulit menutup.','Kompres hangat ringan sesuai anjuran.']),
('a27','avoid',array['Menarik atau memijat wajah dengan kuat.','Gerakan wajah berlebihan hingga lelah.','Paparan angin langsung pada mata yang tidak menutup.']),
('r25','red',array['Kelemahan lengan/tungkai, bicara pelo, atau nyeri kepala hebat.','Mata sangat merah, nyeri, atau penglihatan menurun.','Gejala makin memburuk dengan cepat.']),
('d27','do',array['Lakukan latihan setiap hari, bukan hanya saat sesi terapi.','Gunakan sisi yang lemah pada aktivitas sehari-hari sesuai arahan.','Libatkan keluarga; amankan rumah (lantai tidak licin, pegangan).','Kontrol tekanan darah, gula darah, dan minum obat teratur.']),
('a28','avoid',array['Mengabaikan sisi yang lemah atau menahan posisi lama yang membuat sendi kaku.','Berjalan tanpa pengawasan bila mudah goyah.','Berhenti minum obat tanpa petunjuk dokter.']),
('r26','red',array['Kelemahan, bicara pelo, atau wajah mencong yang baru atau tiba-tiba memburuk.','Nyeri kepala hebat mendadak atau kejang.','Jatuh dengan cedera, sesak napas, atau demam.']),
('a29','avoid',array['Duduk bersila atau menyilang kaki bila memicu nyeri.','Tidur menindih sisi yang nyeri.','Latihan berat sebelum nyeri membaik.','Fleksi panggul dalam disertai putaran (jongkok dalam).']),
('d28','do',array['Tetap bergerak dalam batas nyaman agar sendi tidak kaku.','Lakukan latihan penguatan paha dan pinggul sesuai program.','Jaga berat badan ideal.','Turunkan berat badan bila berlebih.']),
('a30','avoid',array['Memaksa aktivitas atau olahraga sebelum nyeri dan kekuatan membaik.','Pijat keras atau panas berlebih pada cedera baru.','Mengabaikan nyeri tajam saat bergerak.','Fleksi panggul dalam disertai putaran (jongkok dalam).']),
('d29','do',array['Lakukan latihan keseimbangan dan latihan mata-kepala sesuai program.','Bangun dari berbaring secara bertahap (duduk dulu, tunggu, lalu berdiri).','Pastikan rumah aman; gunakan pegangan.']),
('a31','avoid',array['Gerakan kepala mendadak atau berdiri terlalu cepat.','Berkendara saat sedang pusing.','Mendiamkan diri total karena takut pusing.']),
('r27','red',array['Pandangan ganda, bicara pelo, kelemahan atau baal pada wajah/anggota gerak.','Nyeri kepala hebat mendadak atau sulit berjalan.','Pusing disertai pingsan, nyeri dada, atau berdebar hebat.']),
('d30','do',array['Tetap aktif dengan jalan ringan dalam batas nyaman.','Lakukan latihan penguatan pinggul sesuai program.','Atur posisi duduk dan tidur (bantal di antara lutut saat miring).','Turunkan berat badan bila berlebih.']),
('d31','do',array['Latihan dasar panggul dan napas sesuai program, dengan teknik benar.','Atur posisi saat batuk, bersin, atau mengangkat (kontraksi dasar panggul lebih dulu).','Cukup minum dan makan serat agar tidak mengejan.','Naikkan aktivitas bertahap.']),
('a32','avoid',array['Mengejan kuat saat BAB.','Mengangkat beban berat.','Menahan BAK terlalu lama.']),
('r28','red',array['Perdarahan tidak normal, demam, atau cairan berbau.','Nyeri hebat, betis bengkak-nyeri, atau sesak napas.','Urin tidak bisa keluar atau darah dalam urin.']),
('a33','avoid',array['Mengangkat beban berat di atas kepala saat nyeri.','Gerakan menarik atau menyentak mendadak.','Mendiamkan bahu sama sekali.','Gerakan lengan ke atas-belakang secara ekstrem saat fase awal.']),
('d32','do',array['Makan makanan lunak sementara.','Lakukan latihan rahang dan relaksasi sesuai program.','Perbaiki postur kepala-leher.']),
('a34','avoid',array['Mengunyah keras atau permen karet.','Membuka mulut sangat lebar (menguap lebar tanpa topangan).','Menggertakkan gigi atau menopang dagu.']),
('r29','red',array['Rahang terkunci dan tidak bisa dibuka atau ditutup.','Bengkak wajah, demam, atau nyeri hebat setelah benturan.','Gangguan pendengaran atau pusing yang menetap.']),
('d33','do',array['Ikuti instruksi dokter (penyangga, weight bearing, batas gerak).','Lakukan latihan sesuai program dan naikkan bertahap.','Jaga luka tetap bersih dan kering bila ada.','Gunakan alat bantu jalan sesuai anjuran.','Perhatikan tanda bengkak lengan dan jaga kulit lengan.']),
('a35','avoid',array['Berjalan tanpa alas kaki di permukaan keras saat nyeri.','Meningkatkan jarak lari atau aktivitas terlalu cepat.','Sepatu sempit atau hak tinggi.','Meningkatkan jarak lari atau lompat terlalu cepat.'])
insert into public.diagnosis_education(diagnosis_key,display_name,service,icd10,what,cause,recovery,do_list,avoid_list,red_list) values
('bronchiectasis','Bronchiectasis','Cardiorespiratory Physiotherapy','J47','Saluran napas (bronkus) melebar dan rusak sehingga dahak mudah menumpuk dan sering terjadi infeksi.','Infeksi paru berat atau berulang di masa lalu, TB, atau kelainan bawaan.','Kondisi jangka panjang; gejala dapat terkendali dengan latihan bersihan dahak rutin dan pengobatan.','d01','a01','r01'),
('bronchitis','Bronchitis','Cardiorespiratory Physiotherapy','J40','Radang pada saluran napas besar yang menyebabkan batuk berdahak.','Infeksi virus atau bakteri, asap rokok, polusi, debu.','Bronkitis akut umumnya membaik dalam 1-3 minggu (batuk bisa lebih lama); bronkitis kronis butuh penanganan jangka panjang.','d01','a01','r01'),
('broncho pneumonia','Broncho Pneumonia','Cardiorespiratory Physiotherapy','J18.0','Infeksi yang menyebar di beberapa bagian paru (radang paru).','Kuman (bakteri/virus), daya tahan tubuh rendah, lansia atau anak kecil.','Umumnya membaik dalam 1-3 minggu dengan pengobatan; tenaga bisa pulih lebih lama.','d01','a01','r01'),
('bronchospasm','Bronchospasm','Cardiorespiratory Physiotherapy','J98.0','Penyempitan mendadak saluran napas sehingga napas terasa sesak dan berbunyi.','Alergi, udara dingin, debu, asap, infeksi, atau olahraga.','Dapat dikendalikan dengan obat dan teknik napas; mengenali serta menghindari pemicu penting.','d01','a01','r01'),
('chronic obstructive pulmonary disease','Chronic obstructive pulmonary disease','Cardiorespiratory Physiotherapy','J44.9','Penyakit paru kronis yang membuat aliran napas terhambat sehingga mudah sesak, batuk, dan berdahak.','Merokok (penyebab utama), polusi, paparan debu atau asap kerja.','Tidak sembuh total, tetapi gejala dan kemampuan aktivitas dapat meningkat dengan latihan dan pengobatan.','d01','a01','r01'),
('pneumonia','Pneumonia','Cardiorespiratory Physiotherapy','J18.9','Infeksi yang menyebabkan peradangan pada kantong udara di paru.','Bakteri, virus, atau jamur; lebih mudah terjadi saat daya tahan tubuh turun.','Umumnya membaik dalam 1-3 minggu; tenaga dapat pulih 4-6 minggu atau lebih.','d01','a01','r01'),
('post-covid condition','Post-COVID condition','Cardiorespiratory Physiotherapy','U09.9','Gejala yang menetap atau muncul setelah COVID-19, seperti sesak, mudah lelah, dan sulit konsentrasi.','Dampak infeksi pada paru, otot, saraf, dan tubuh secara umum.','Bervariasi dari beberapa minggu hingga berbulan-bulan; naikkan aktivitas bertahap dan jangan memaksa.','d01','a02','r01'),
('pulmonary fibrosis','Pulmonary fibrosis','Cardiorespiratory Physiotherapy','J84.1','Jaringan paru mengeras dan berparut sehingga paru sulit mengembang dan tubuh kekurangan oksigen.','Paparan zat atau obat tertentu, penyakit autoimun, infeksi, atau tidak diketahui.','Umumnya kronis; latihan dan teknik napas membantu menjaga kemampuan aktivitas.','d01','a01','r01'),
('respiratory failure','Respiratory failure','Cardiorespiratory Physiotherapy','J96.9','Paru tidak mampu memenuhi kebutuhan oksigen atau membuang karbon dioksida dengan baik.','Penyakit paru berat, pneumonia, kelemahan otot napas, atau kondisi kritis.','Bergantung penyebab; rehabilitasi bertahap membantu mengembalikan tenaga dan napas.','d01','a01','r01'),
('chronic pain syndrome','Chronic pain syndrome','Chronic Pain Management','R52.2','Nyeri yang berlangsung lebih dari 3 bulan dan sistem saraf menjadi lebih sensitif, tidak selalu berarti masih ada kerusakan jaringan.','Cedera atau penyakit sebelumnya, stres, kurang tidur, kurang aktivitas, kecemasan.','Fokus pada fungsi dan kualitas hidup; membaik bertahap dengan aktivitas bertahap.','d02','a03','r02'),
('frailty','Frailty','Geriatric Rehabilitation','R54','Kondisi tubuh rentan karena cadangan tenaga dan kekuatan menurun, sehingga mudah sakit dan jatuh.','Bertambahnya usia, penyakit kronis, kurang gizi, kurang aktivitas.','Dapat diperbaiki dengan latihan kekuatan, gizi cukup, dan aktivitas teratur.','d03','a04','r03'),
('kelemahan umum','Kelemahan Umum','Geriatric Rehabilitation','R53','Tubuh terasa lemas dan kurang bertenaga untuk beraktivitas.','Sakit berkepanjangan, tirah baring, kurang gizi, kurang gerak, penyakit kronis.','Membaik bertahap dengan aktivitas dan latihan yang dinaikkan pelan.','d03','a04','r03'),
('malaise dan fatigue','Malaise dan Fatigue','Geriatric Rehabilitation','R53','Rasa tidak enak badan dan mudah lelah yang tidak sebanding dengan aktivitas.','Infeksi, kurang tidur, stres, anemia, kondisi medis lain, atau kurang aktivitas.','Bergantung penyebab; aktivitas bertahap dan tidur cukup membantu.','d03','a04','r03'),
('osteoporosis dengan fraktur','Osteoporosis dengan Fraktur','Geriatric Rehabilitation','M80.9','Tulang menjadi rapuh dan berongga sehingga mudah patah; pada kondisi ini sudah terjadi patah tulang.','Usia, menopause, kurang kalsium/vitamin D, kurang gerak, obat steroid jangka panjang.','Patah tulang umumnya menyatu dalam 6-12 minggu; mencegah patah berikutnya butuh latihan beban, gizi, dan obat.','d03','a04','r03'),
('penurunan keseimbangan','Penurunan Keseimbangan','Geriatric Rehabilitation','R26.8','Kemampuan menjaga posisi tubuh menurun sehingga mudah goyah.','Usia, otot lemah, gangguan telinga dalam atau penglihatan, gangguan saraf, efek obat.','Dapat membaik dengan latihan keseimbangan teratur.','d03','a04','r03'),
('polyosteoarthritis','Polyosteoarthritis','Geriatric Rehabilitation','M15.9','Pengapuran pada beberapa sendi sekaligus.','Usia, berat badan berlebih, cedera lama, beban berulang, faktor keturunan.','Kondisi kronis; nyeri dan fungsi dapat membaik dengan latihan teratur dan penurunan berat badan.','d03','a04','r03'),
('reduced mobility','Reduced Mobility','Geriatric Rehabilitation','Z74.0','Kemampuan berpindah dan bergerak berkurang.','Nyeri, kelemahan otot, penyakit, atau setelah rawat inap.','Membaik bertahap dengan latihan dan aktivitas yang dinaikkan pelan.','d03','a04','r03'),
('repeated falls','Repeated Falls','Geriatric Rehabilitation','R29.6 / Z91.8','Jatuh yang terjadi berulang.','Otot lemah, keseimbangan terganggu, pusing, efek obat, penglihatan, lingkungan rumah.','Risiko dapat diturunkan dengan latihan, pengaturan obat, dan rumah yang aman.','d03','a04','r03'),
('risiko jatuh','Risiko Jatuh','Geriatric Rehabilitation','Z91.8','Kemungkinan lebih tinggi untuk jatuh, atau sebelumnya pernah jatuh.','Otot lemah, keseimbangan terganggu, pusing, efek obat, penglihatan, lingkungan rumah.','Risiko dapat diturunkan dengan latihan, pengaturan obat, dan rumah yang aman.','d03','a04','r03'),
('senility','Senility','Geriatric Rehabilitation','R54','Kondisi tubuh rentan karena cadangan tenaga dan kekuatan menurun, sehingga mudah sakit dan jatuh.','Bertambahnya usia, penyakit kronis, kurang gizi, kurang aktivitas.','Dapat diperbaiki dengan latihan kekuatan, gizi cukup, dan aktivitas teratur.','d03','a04','r03'),
('konsultasi','Konsultasi','Konsultasi','Z71.9','Pertemuan untuk membahas keluhan Anda, hasil pemeriksaan, dan rencana tindakan.','Sesuai keluhan yang Anda sampaikan.','Rencana akan ditentukan setelah pemeriksaan.','d04','a05','r04'),
('abdominal pain','Abdominal Pain','Musculoskeletal Treatment','R10.4','Nyeri di perut; sebagian bisa berasal dari otot dan sambungan dinding perut.','Ketegangan atau cedera otot dinding perut, saraf yang terjepit, atau penyebab organ dalam yang perlu disingkirkan dokter.','Bergantung penyebab; nyeri dinding perut umumnya membaik dalam beberapa minggu.','d05','a06','r05'),
('achilles tendon rupture','Achilles tendon rupture','Musculoskeletal Treatment','S86.0','Tendon tumit (Achilles) sobek sebagian atau seluruhnya.','Gerakan loncat atau akselerasi mendadak, usia, penggunaan obat tertentu.','Pemulihan penuh biasanya 6-12 bulan; ikuti protokol dokter.','d06','a07','r06'),
('acquired absence of arm below elbow','Acquired absence of arm below elbow','Musculoskeletal Treatment','Z89.2','Kehilangan sebagian anggota gerak (amputasi).','Cedera berat, gangguan pembuluh darah atau diabetes, infeksi, atau tumor.','Adaptasi dan latihan dengan prostesis berlangsung berbulan-bulan; latihan rutin menentukan hasil.','d07','a07','r06'),
('acquired absence of both legs','Acquired absence of both legs','Musculoskeletal Treatment','Z89.7','Kehilangan sebagian anggota gerak (amputasi).','Cedera berat, gangguan pembuluh darah atau diabetes, infeksi, atau tumor.','Adaptasi dan latihan dengan prostesis berlangsung berbulan-bulan; latihan rutin menentukan hasil.','d07','a07','r06'),
('acquired absence of leg below knee','Acquired absence of leg below knee','Musculoskeletal Treatment','Z89.5','Kehilangan sebagian anggota gerak (amputasi).','Cedera berat, gangguan pembuluh darah atau diabetes, infeksi, atau tumor.','Adaptasi dan latihan dengan prostesis berlangsung berbulan-bulan; latihan rutin menentukan hasil.','d07','a07','r06'),
('acromioclavicular sprain','Acromioclavicular Sprain','Musculoskeletal Treatment','S43.5','Cedera ligamen di sendi ujung bahu (sendi akromioklavikular).','Jatuh pada bahu atau benturan langsung.','Ringan: 2-4 minggu; sedang-berat: hingga 12 minggu atau lebih.','d08','a08','r07'),
('adductor strain','Adductor strain','Musculoskeletal Treatment','S76.2','Cedera otot di sisi dalam paha atau selangkangan.','Gerakan mendadak (menendang, berlari mengubah arah), beban berlebih.','Ringan 1-3 minggu, sedang 3-8 minggu.','d08','a08','r07'),
('ankle instability, chronic','Ankle instability, chronic','Musculoskeletal Treatment','M24.2','Pergelangan kaki sering terasa goyah dan mudah terkilir berulang.','Terkilir sebelumnya yang tidak pulih sempurna, otot dan keseimbangan lemah.','Membaik dalam 6-12 minggu dengan latihan keseimbangan dan penguatan.','d09','a09','r08'),
('ankle sprain','Ankle sprain','Musculoskeletal Treatment','S93.4','Terkilir pada pergelangan atau kaki; ligamen teregang atau sobek.','Menapak tidak rata, terpeleset, atau berubah arah mendadak saat olahraga.','Ringan-sedang umumnya 2-6 minggu; latihan keseimbangan mencegah kambuh.','d08','a08','r07'),
('ankylosing spondylitis','Ankylosing spondylitis','Musculoskeletal Treatment','M45','Radang kronis pada tulang belakang dan sendi panggul-tulang belakang yang membuat kaku, terutama pagi hari.','Faktor autoimun dan keturunan.','Kondisi jangka panjang; latihan rutin dan obat menjaga kelenturan dan mengurangi nyeri.','d10','a10','r09'),
('anterior lateral ligament','Anterior Lateral Ligament','Musculoskeletal Treatment','S83.6 *','Cedera ligamen di sisi luar lutut yang membantu stabilitas putaran lutut.','Gerakan memutar lutut mendadak, sering bersamaan dengan cedera ACL.','Membaik bertahap dalam beberapa bulan dengan latihan; pada cedera berat dapat perlu tindakan.','d08','a08','r07'),
('anterior pelvic tilt','Anterior pelvic tilt','Musculoskeletal Treatment','R29.3 *','Panggul condong ke depan sehingga punggung bawah melengkung berlebih.','Otot pinggul depan dan punggung ketat, otot perut dan bokong lemah, duduk lama.','Membaik dalam beberapa minggu hingga bulan dengan latihan dan kebiasaan duduk yang baik.','d11','a11','r10'),
('anterior shoulder dislocation','Anterior shoulder dislocation','Musculoskeletal Treatment','S43.0','Sendi bahu lepas atau bergeser dari posisinya, atau terasa tidak stabil.','Jatuh, benturan, gerakan lengan ekstrem, atau sendi yang longgar.','Setelah reposisi, pemulihan sekitar 6-12 minggu; latihan penguatan menurunkan risiko lepas berulang.','d08','a12','r07'),
('anterior tibialis tendinitis','Anterior tibialis tendinitis','Musculoskeletal Treatment','M76.8','Radang tendon di depan pergelangan kaki atau tulang kering.','Berjalan atau berlari menanjak/turun berlebihan, sepatu terlalu ketat, aktivitas meningkat mendadak.','Umumnya membaik dalam 2-8 minggu dengan pengaturan beban dan latihan.','d09','a09','r08'),
('autoimun','Autoimun','Musculoskeletal Treatment','M35.9 *','Kondisi saat sistem kekebalan tubuh menyerang jaringan sendiri sehingga menimbulkan radang dan nyeri.','Faktor keturunan, hormon, dan pemicu lingkungan.','Kondisi jangka panjang yang terkendali dengan obat, istirahat cukup, dan latihan sesuai kemampuan.','d10','a10','r09'),
('avulsion fracture','Avulsion Fracture','Musculoskeletal Treatment','T14.2 *','Patah tulang kecil akibat tarikan kuat otot, tendon, atau ligamen yang menyobek sebagian tulang.','Gerakan mendadak dan kuat, olahraga cepat, anak atau remaja yang masih tumbuh.','Umumnya sembuh dalam 6-8 minggu; ikuti anjuran dokter.','d06','a07','r06'),
('baker''s cyst','Baker''s cyst','Musculoskeletal Treatment','M71.2','Kantung berisi cairan di belakang lutut.','Biasanya akibat masalah di dalam sendi lutut (pengapuran, meniscus).','Membaik bila penyebab ditangani; ukuran dapat mengecil bertahap.','d12','a13','r11'),
('biceps strain','Biceps Strain','Musculoskeletal Treatment','S46.1','Cedera otot lengan atas bagian depan (biseps).','Mengangkat atau menarik beban mendadak, olahraga.','Ringan 1-3 minggu, sedang 3-6 minggu.','d08','a08','r07'),
('bicipital instability','Bicipital instability','Musculoskeletal Treatment','M75.2','Radang atau ketidakstabilan tendon biseps di bahu depan.','Gerakan mengangkat atau melempar berulang, beban berlebih.','Umumnya membaik dalam 4-8 minggu dengan latihan.','d13','a14','r12'),
('bicipital tendinitis','Bicipital tendinitis','Musculoskeletal Treatment','M75.2','Radang atau ketidakstabilan tendon biseps di bahu depan.','Gerakan mengangkat atau melempar berulang, beban berlebih.','Umumnya membaik dalam 4-8 minggu dengan latihan.','d13','a14','r12'),
('bipartite patella','Bipartite patella','Musculoskeletal Treatment','Q74.1 *','Tempurung lutut terbentuk dari dua bagian tulang sejak lahir.','Variasi bentuk tulang bawaan; sering tanpa gejala, dapat nyeri bila terjadi tarikan berulang atau benturan.','Banyak membaik dengan pengaturan aktivitas dan latihan.','d12','a13','r11'),
('bunion','Bunion','Musculoskeletal Treatment','M20.1','Tonjolan di pangkal ibu jari kaki karena ibu jari bergeser ke arah jari lain.','Bentuk kaki dan keturunan, sepatu sempit atau hak tinggi.','Tidak mengembalikan bentuk, tetapi nyeri dapat berkurang dengan alas kaki yang tepat dan latihan.','d09','a09','r08'),
('burn of lower limb','Burn of lower limb','Musculoskeletal Treatment','T24.-','Luka bakar atau akibat luka bakar yang dapat menyebabkan parut dan kaku sendi.','Api, air panas, listrik, atau bahan kimia.','Bergantung kedalaman luka; latihan dan posisi yang tepat mencegah kaku sendi dan parut mengerut.','d06','a07','r06'),
('burn of trunk','Burn of trunk','Musculoskeletal Treatment','T21.-','Luka bakar atau akibat luka bakar yang dapat menyebabkan parut dan kaku sendi.','Api, air panas, listrik, atau bahan kimia.','Bergantung kedalaman luka; latihan dan posisi yang tepat mencegah kaku sendi dan parut mengerut.','d06','a07','r06'),
('burn of upper limb','Burn of upper limb','Musculoskeletal Treatment','T22.-','Luka bakar atau akibat luka bakar yang dapat menyebabkan parut dan kaku sendi.','Api, air panas, listrik, atau bahan kimia.','Bergantung kedalaman luka; latihan dan posisi yang tepat mencegah kaku sendi dan parut mengerut.','d06','a07','r06'),
('calcaneal apophysitis (sever''s disease)','Calcaneal apophysitis (Sever''s disease)','Musculoskeletal Treatment','M92.8','Nyeri di tumit pada anak dan remaja saat masa pertumbuhan.','Tarikan otot betis pada tulang tumit yang masih tumbuh, aktivitas lari/lompat berlebih.','Membaik dalam beberapa minggu hingga bulan; hilang setelah masa pertumbuhan.','d09','a09','r08'),
('calcaneus spur','Calcaneus spur','Musculoskeletal Treatment','M77.3','Tonjolan tulang di tumit.','Tarikan berulang fasia telapak kaki, berdiri atau berjalan lama.','Banyak membaik dalam 6-12 minggu dengan peregangan dan alas kaki yang menopang.','d09','a09','r08'),
('calcific tendinitis of shoulder','Calcific tendinitis of shoulder','Musculoskeletal Treatment','M75.3','Endapan kalsium di tendon bahu yang menimbulkan nyeri.','Penyebab tidak selalu jelas; sering pada usia 30-60 tahun.','Dapat sembuh sendiri; fase penyerapan bisa sangat nyeri; beberapa bulan.','d13','a14','r12'),
('calf muscle tightness','Calf muscle tightness','Musculoskeletal Treatment','M62.8','Otot betis terasa kencang dan kaku.','Kurang peregangan, aktivitas berulang, sepatu hak tinggi.','Membaik dalam beberapa minggu dengan peregangan rutin.','d09','a09','r08'),
('cervical disc displacement','Cervical disc displacement','Musculoskeletal Treatment','M50.2','Bantalan sendi leher bergeser atau menipis sehingga dapat menekan saraf.','Penuaan, postur buruk, angkat beban, cedera.','Banyak membaik dalam 6-12 minggu dengan latihan.','d14','a15','r13'),
('cervicalgia','Cervicalgia','Musculoskeletal Treatment','M54.2','Nyeri pada leher.','Postur menunduk lama, ketegangan otot, tidur salah posisi, stres.','Umumnya membaik dalam 2-6 minggu dengan latihan dan perbaikan postur.','d14','a15','r13'),
('cervicogenic headache','Cervicogenic headache','Musculoskeletal Treatment','M53.0','Nyeri kepala yang berasal dari masalah pada leher.','Sendi atau otot leher bagian atas yang kaku atau tegang.','Membaik dalam beberapa minggu dengan latihan leher.','d15','a16','r14'),
