-- Template edukasi pasien per diagnosa (Edukasi_Pasien_Kaffah_329_Diagnosa.xlsx).
-- Daftar tindakan/hindari/tanda bahaya dipakai bersama banyak diagnosa, jadi disimpan sekali di education_lists.
create table if not exists public.education_lists (
  id text primary key, kind text not null check (kind in ('do', 'avoid', 'red')), items text[] not null
);
create table if not exists public.diagnosis_education (
  diagnosis_key text primary key, display_name text not null, service text, icd10 text,
  what text, cause text, recovery text,
  do_list text references public.education_lists(id), avoid_list text references public.education_lists(id), red_list text references public.education_lists(id)
);
alter table public.education_lists enable row level security;
alter table public.diagnosis_education enable row level security;
create policy "education_lists_read" on public.education_lists for select to authenticated using (true);
create policy "diagnosis_education_read" on public.diagnosis_education for select to authenticated using (true);
create policy "education_lists_write" on public.education_lists for all to authenticated
  using (public.get_my_role() = 'super_admin') with check (public.get_my_role() = 'super_admin');
create policy "diagnosis_education_write" on public.diagnosis_education for all to authenticated
  using (public.get_my_role() = 'super_admin') with check (public.get_my_role() = 'super_admin');
alter table public.medical_records add column if not exists education text;

on conflict (id) do nothing;

on conflict (diagnosis_key) do nothing;
